-- move every date forward by whole days, so the sample ends on the day this file runs
do $shift$
declare
  v_days integer := greatest(floor(extract(epoch from (now() - timestamptz '2026-11-11 14:45:00+00')) / 86400)::int, 0);
  r record;
begin
  for r in
    select c.table_name, c.column_name, c.data_type
      from information_schema.columns c
     where c.table_schema = 'public'
       and c.data_type in ('timestamp with time zone', 'timestamp without time zone', 'date')
       and c.table_name = any (array['accounts','app_settings','areas','branch_tax_settings','branches','brands','cancel_reasons','categories','companies','customer_feedback','customer_ledger','customers','discounts','expense_categories','expenses','fiscal_periods','goods_receipt_items','goods_receipts','ingredient_cost_history','ingredients','journal_entries','journal_entry_lines','order_items','order_logs','order_sequences','order_station_status','orders','payments','payroll_lines','payroll_runs','pos_cash_moves','pos_days','pos_shifts','products','purchase_order_items','purchase_orders','recipes','roles','service_requests','staff','staff_attendance','staff_ledger','stock_movements','supplier_invoices','supplier_ledger','supplier_payments','supplier_prices','suppliers','tables','warehouse_stock','warehouses','waste_logs'])
       and c.table_name <> 'fiscal_periods'
       and not (c.table_name = 'customers' and c.column_name = 'birthday')
  loop
    -- two steps (far away, then back) so rows never collide on a unique date
    if r.data_type = 'date' then
      execute format('update public.%I set %I = %I + %s where %I is not null', r.table_name, r.column_name, r.column_name, v_days + 40000, r.column_name);
      execute format('update public.%I set %I = %I - 40000 where %I is not null', r.table_name, r.column_name, r.column_name, r.column_name);
    else
      execute format('update public.%I set %I = %I + make_interval(days => %s) where %I is not null', r.table_name, r.column_name, r.column_name, v_days + 40000, r.column_name);
      execute format('update public.%I set %I = %I - make_interval(days => 40000) where %I is not null', r.table_name, r.column_name, r.column_name, r.column_name);
    end if;
  end loop;
  update public.payroll_runs set period = date_trunc('month', period)::date;
  update public.expenses set recurring_period = date_trunc('month', recurring_period)::date where recurring_period is not null;
  update public.expense_recurring set last_period = date_trunc('month', last_period)::date where last_period is not null;
  raise notice 'demo dates moved forward % days', v_days;
end;
$shift$;

-- accounting months: from the first entry to 3 months ahead, all open
delete from public.fiscal_periods;
select c.id,
       (array['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'])[extract(month from m)::int] || ' ' || extract(year from m)::int,
       m::date, (m + interval '1 month - 1 day')::date, 'open'
  from public.companies c
 cross join generate_series(date_trunc('month', (select min(entry_date) from public.journal_entries)),
                            date_trunc('month', current_date) + interval '3 months', interval '1 month') m;

-- every copy gets its own secret QR / feedback links
update public.tables set qr_token = default where qr_token is not null;
update public.branches set public_token = default, has_store_server = false;
update public.app_settings set data = data || jsonb_build_object('mode', 'none') where section = 'offline';

set local session_replication_role = origin;

do $check$
begin
  if (select count(*) from public.orders) < 1000 or (select count(*) from public.staff) <> 8 or (select count(*) from public.roles) <> 5 then
    raise exception 'demo data check failed';
  end if;
  raise notice 'MOTIONPOS-DEMO-DATA-OK';
end;
$check$;

notify pgrst, 'reload schema';

commit;
